from itertools import permutations

def get_palindrome_subsequences(message):
    palindrome_subsequences = []
    for i in range(len(message) - 1):
        subsequences = []
        for j in range(i + 1, len(message)):
            if message[i:j] == message[i:j][::-1] and len(subsequences) < len(message) - j + i + 1:
                subsequences.append(message[i:j])
        palindrome_subsequences.extend(subsequences)
    return sorted(set(subsequences) for subsequences in permutations(''.join(message) for _ in range(len(subsequences))), key=len)

def decrypt_message(message):
    decoded_message = ''.join(message)
    decrypted_message = ''
    for i in range(len(decoded_message)):
        for subsequence in get_palindrome_subsequences(decoded_message):
            if i < len(subsequence) and subsequence[i] == decoded_message[i]:
                decrypted_message += subsequence[i]
                break
    return decrypted_message

