class Room:
    def __init__(self):
        self.warriors = []
        self.combat_power = {}

    def increase_combat_power(self, warrior, C):
        if warrior in self.combat_power:
            self.combat_power[warrior] += C
            self.warriors.remove(warrior)
            heapq.heappush(self.warriors, (-self.combat_power[warrior], warrior))
        else:
            self.combat_power[warrior] = C
            self.warriors.append((warrior, C))
            heapq.heapify(self.warriors)

