    MODULUS = 10000007

    # Helper function to calculate combinations
    def combinations(n, r):
        if r > n:
            return 0
        elif r == n:
            return 1
        else:
            return (combinations(n - 1, r - 1) + combinations(n - 1, r)) % MODULUS

